def compute(vars):
    useful_life_years = vars["v1"]
    if useful_life_years == 0:
        return None
    yearly_depreciation_rate = 100 / useful_life_years
    return {
        "value": yearly_depreciation_rate,
        "trace": {
            "useful_life_years": useful_life_years,
            "yearly_depreciation_rate": yearly_depreciation_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
